    // invalid  hour
    expr = new ScheduleExpression().dayOfMonth(6).hour("24/2").minute(1).second(59).start(new Date(0));
    parseExceptionThrown = false;
    try {
        new EJBCronTrigger(expr);
    } catch (final ParseException e) {
