@Test
public void test() throws Exception {
    final URI[] uris = uris("one://localhost:1243", "two://localhost:1243", "three://localhost:1243", "four://localhost:1243");
    ClusterMetaData cluster = new ClusterMetaData(System.currentTimeMillis(), uris);
    Iterable<URI> iterable = new RoundRobinConnectionStrategy().createIterable(cluster);
    {
        Iterator<URI> iterator = iterable.iterator();
        Assert.assertTrue(iterator.hasNext());
        Assert.assertEquals(uris[0], iterator.next());
        Assert.assertTrue(iterator.hasNext());
        Assert.assertEquals(uris[1], iterator.next());
        Assert.assertTrue(iterator.hasNext());
        Assert.assertEquals(uris[2], iterator.next());
        Assert.assertTrue(iterator.hasNext());
        Assert.assertEquals(uris[3], iterator.next());
        Assert.assertTrue(!iterator.hasNext());
        try {
            iterator.next();
            Assert.fail("Expected NoSuchElementException");
        } catch (NoSuchElementException e) {
            // pass
        }
    }
    {
        Iterator<URI> prep = iterable.iterator();
        prep.next();
        prep.next();
        Iterator<URI> iterator = iterable.iterator();
        Assert.assertEquals(uris[2], iterator.next());
        Assert.assertEquals(uris[3], iterator.next());
        Assert.assertEquals(uris[0], iterator.next());
        Assert.assertEquals(uris[1], iterator.next());
    }
}

@Test
public void testRandom() throws Exception {
    final URI[] uris = uris("one://localhost:1243", "two://localhost:1243", "three://localhost:1243", "four://localhost:1243");
    ClusterMetaData cluster = new ClusterMetaData(System.currentTimeMillis(), uris);
    Iterable<URI> iterable = new StickyConnectionStrategy(new RandomConnectionStrategy()).createIterable(cluster);
    assertIteration(uris, iterable);
    {
        // Stick to uri 2
        URI uri = uris[2];
        cluster.setLastLocation(uri);
        Assert.assertEquals(uri, iterable.iterator().next());
        Assert.assertEquals(uri, iterable.iterator().next());
        Assert.assertEquals(uri, iterable.iterator().next());
        Assert.assertEquals(uri, iterable.iterator().next());
    }
    {
        // Stick to uri 2
        URI uri = uris[3];
        cluster.setLastLocation(uri);
        Assert.assertEquals(uri, iterable.iterator().next());
        Assert.assertEquals(uri, iterable.iterator().next());
        Assert.assertEquals(uri, iterable.iterator().next());
        Assert.assertEquals(uri, iterable.iterator().next());
    }
    assertIteration(uris, iterable);
}

